<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>DUSTLINE — a three.js tactical FPS</title>
<style>
  :root {
    --canvas: #2b2119;
    --surface: #242019;
    --hairline: #3a332a;
    --ink: #e9e6df;
    --muted: #98a0a8;
    --accent: #f0a830;
    --danger: #c94f3d;
