  #game, #game canvas { position: fixed; inset: 0; display: block; }
  #hud { position: fixed; inset: 0; pointer-events: none; }
  .hidden { display: none !important; }

  /* crosshair: gap follows live spread via --gap */
  #crosshair { position: fixed; left: 50%; top: 50%; width: 26px; height: 26px; transform: translate(-50%, -50%); --gap: 5px; }
  #crosshair i { position: absolute; background: var(--ink); opacity: .9; box-shadow: 0 0 2px #000; }
  #crosshair i:nth-child(1) { left: 12px; top: 0; width: 2px; height: 7px; transform: translateY(calc(-1 * var(--gap))); }
  #crosshair i:nth-child(2) { left: 12px; bottom: 0; width: 2px; height: 7px; transform: translateY(var(--gap)); }
  #crosshair i:nth-child(3) { top: 12px; left: 0; height: 2px; width: 7px; transform: translateX(calc(-1 * var(--gap))); }
  #crosshair i:nth-child(4) { top: 12px; right: 0; height: 2px; width: 7px; transform: translateX(var(--gap)); }
  #crosshair .dot { position: absolute; left: 12px; top: 12px; width: 2px; height: 2px; background: var(--ink); }

  #hitmarker { position: fixed; left: 50%; top: 50%; width: 30px; height: 30px; transform: translate(-50%, -50%) rotate(45deg); opacity: 0; transition: opacity 90ms linear; }
  #hitmarker.on { opacity: 1; }
  #hitmarker i { position: absolute; background: var(--ink); }
  #hitmarker.kill i { background: var(--danger); }
  #hitmarker i:nth-child(1) { left: 14px; top: 0; width: 2px; height: 9px; }
  #hitmarker i:nth-child(2) { left: 14px; bottom: 0; width: 2px; height: 9px; }
  #hitmarker i:nth-child(3) { top: 14px; left: 0; height: 2px; width: 9px; }
