  #dmgnum.on { opacity: 1; }

  #vignette { position: fixed; inset: 0; pointer-events: none; opacity: 0; transition: opacity 500ms ease-out;
    background: radial-gradient(ellipse at center, transparent 55%, rgba(201, 79, 61, 0.55) 100%); }
  #vignette.flash { transition: opacity 60ms linear; }

