  #buymenu { position: fixed; inset: 0; display: grid; place-items: center; background: rgba(20,16,12,.72); pointer-events: auto; }
  #buymenu .panel { width: min(680px, 94vw); background: var(--surface); border: 1px solid var(--hairline); border-radius: var(--radius-panel); padding: 24px 28px; }
