  #buy-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 10px; }
  .buy-card { font: inherit; text-align: left; padding: 14px; background: #1a1712; border: 1px solid var(--hairline); border-radius: var(--radius-control); color: var(--ink); cursor: pointer; display: grid; gap: 4px; }
