  /* overlay: start / pause / end */
  .overlay { position: fixed; inset: 0; display: grid; place-items: center; padding: 24px; background: rgba(26, 23, 18, .86); pointer-events: auto; }
  .overlay[hidden] { display: none; }
  .panel { width: min(460px, 100%); padding: 32px; background: var(--surface); border: 1px solid var(--hairline); border-radius: var(--radius-panel); }
  .panel h1 { margin: 0 0 8px; font-size: 34px; line-height: 1.15; font-weight: 600; letter-spacing: -0.02em; }
  .panel p { margin: 0 0 24px; font-size: 15px; line-height: 1.55; color: var(--muted); }
  #play { font: inherit; font-weight: 600; padding: 12px 18px; border: 1px solid var(--accent); border-radius: var(--radius-control); background: var(--accent); color: var(--canvas); cursor: pointer; }
  #play:hover { background: var(--ink); border-color: var(--ink); }
  .keys { margin: 24px 0 0; padding: 0; list-style: none; display: grid; gap: 8px; font-size: 13px; color: var(--muted); }
  .keys li { display: flex; align-items: center; gap: 8px; flex-wrap: wrap; }
  .keys kbd { min-width: 24px; padding: 2px 6px; border: 1px solid var(--hairline); border-radius: var(--radius-panel); font-family: var(--font-readout); font-size: 12px; color: var(--ink); text-align: center; }
</style>
