    const dist = Math.hypot(dx, dz);
    if (dist < 0.05) return true;
    const vx = (dx / dist) * speed;
    const vz = (dz / dist) * speed;
    bot.pos.x += vx * dt;
    bot.pos.z += vz * dt;
