        if (t < 0 || t > maxDist) continue;
        if (!best || t < best.t) {
          best = {
            bot, part: s.part, mul: s.mul, t,
            point: new THREE.Vector3(origin.x + dir.x * t, origin.y + dir.y * t, origin.z + dir.z * t),
          };
